@push('page-styles')
<style>
    .auth-page{position:relative;isolation:isolate;display:grid;min-height:100vh;grid-template-columns:minmax(0,1.15fr) minmax(420px,.85fr);align-items:center;gap:50px;overflow:hidden;padding:135px clamp(24px,6vw,100px) 65px;color:#172033}
    .auth-page:before{position:absolute;z-index:-3;inset:-6%;content:"";background:url("{{ asset('asset/media/auth-fashion-classic-bg.png') }}") center/cover no-repeat;animation:authBackgroundMove 34s cubic-bezier(.45,.05,.55,.95) infinite alternate;will-change:transform}
    .auth-page:after{position:absolute;z-index:-2;inset:0;content:"";background:linear-gradient(90deg,rgba(35,27,20,.6) 0%,rgba(55,43,31,.28) 46%,rgba(244,236,222,.13) 100%)}
    @keyframes authBackgroundMove{0%{transform:scale(1.045) translate3d(-.7%,.25%,0)}50%{transform:scale(1.075) translate3d(.35%,-.35%,0)}100%{transform:scale(1.105) translate3d(1.1%,-.7%,0)}}
    .auth-visual-copy{align-self:stretch;display:flex;max-width:680px;flex-direction:column;justify-content:space-between;padding:15px 0 25px;color:#fff;text-shadow:0 2px 20px rgba(0,0,0,.2)}.auth-visual-brand{display:inline-flex;align-items:center;gap:11px;width:max-content;color:#fff;text-decoration:none}.auth-visual-brand>span{display:grid;width:42px;height:42px;place-items:center;border:1px solid rgba(255,255,255,.35);border-radius:12px;background:rgba(255,255,255,.16);backdrop-filter:blur(12px)}.auth-visual-brand strong{font-size:16px;letter-spacing:.08em;text-transform:uppercase}.auth-visual-message>span{display:block;margin-bottom:14px;font-size:11px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}.auth-visual-message h2{max-width:600px;margin:0;font-size:clamp(42px,5vw,76px);line-height:.98;letter-spacing:-.045em}.auth-visual-message p{max-width:560px;margin:20px 0 24px;color:rgba(255,255,255,.86);font-size:15px;line-height:1.75}.auth-visual-points{display:flex;flex-wrap:wrap;gap:9px}.auth-visual-points small{display:inline-flex;align-items:center;gap:7px;padding:9px 12px;border:1px solid rgba(255,255,255,.24);border-radius:999px;background:rgba(13,29,33,.22);font-weight:750;backdrop-filter:blur(10px)}
    .auth-card{position:relative;width:min(490px,100%);box-sizing:border-box;justify-self:end;padding:38px;border:1px solid rgba(255,255,255,.7);border-radius:24px;background:rgba(255,255,255,.9);box-shadow:0 30px 90px rgba(15,23,42,.22);backdrop-filter:blur(24px);animation:authCardEnter .65s cubic-bezier(.2,.75,.25,1) both}.auth-card-scroll{max-height:calc(100vh - 175px);overflow:auto;scrollbar-width:thin}@keyframes authCardEnter{from{opacity:0;transform:translateY(24px) scale(.98)}to{opacity:1;transform:none}}.auth-card>span{color:#0f766e;font-size:10px;font-weight:900;letter-spacing:.16em;text-transform:uppercase}.auth-card h1{margin:8px 0 8px;font-size:clamp(30px,3vw,39px);line-height:1.08;letter-spacing:-.03em}.auth-card>p{margin:0 0 25px;color:#64748b;font-size:14px;line-height:1.65}.auth-heading-icon{display:grid;width:48px;height:48px;margin:16px 0 15px;place-items:center;border-radius:14px;background:linear-gradient(135deg,#ccfbf1,#dbeafe);color:#0f766e;font-size:19px}
    .auth-status{margin-bottom:16px;padding:11px 13px;border:1px solid #a7f3d0;border-radius:9px;background:#ecfdf5;color:#047857;font-size:13px}.auth-field{margin-bottom:15px}.auth-field label{display:block;margin-bottom:6px;color:#334155;font-size:11px;font-weight:850}.auth-field input[type=text],.auth-field input[type=email],.auth-field input[type=password],.auth-field input[type=text][name=password],.auth-field input[type=text][name=password_confirmation]{width:100%;min-height:46px;box-sizing:border-box;padding:11px 13px;border:1px solid #cbd5e1;border-radius:10px;background:rgba(255,255,255,.82);color:#172033;font:inherit;font-size:13px;outline:none;transition:border .2s,box-shadow .2s,background .2s}.auth-field input::placeholder{color:#a0aec0}.auth-field input:focus{border-color:#0f766e;background:#fff;box-shadow:0 0 0 4px rgba(15,118,110,.1)}.auth-error{margin:6px 0 0;color:#be123c;font-size:11px}.auth-check{display:flex;align-items:center;gap:8px;color:#64748b;font-size:12px}.auth-check input{accent-color:#0f766e}.auth-login-options{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:4px 0 20px}.auth-login-options a,.auth-row a{color:#0f766e;font-size:12px;font-weight:850}.auth-row{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:21px}.auth-submit{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:44px;padding:0 18px;border:0;border-radius:10px;background:linear-gradient(135deg,#172033,#24465a);box-shadow:0 10px 22px rgba(23,32,51,.18);color:#fff;font:inherit;font-size:13px;font-weight:850;cursor:pointer;transition:transform .2s,box-shadow .2s}.auth-submit:hover{transform:translateY(-2px);box-shadow:0 14px 28px rgba(23,32,51,.25)}.auth-submit-wide{width:100%}.auth-switch{margin:21px 0 0!important;padding-top:18px;border-top:1px solid #e7ebf0;text-align:center!important;color:#64748b!important;font-size:12px!important}.auth-switch a{color:#0f766e;font-weight:850}
    .auth-password-input{position:relative}.auth-password-input input{padding-right:49px!important}.auth-password-toggle{position:absolute;top:50%;right:7px;display:grid;width:34px;height:34px;place-items:center;transform:translateY(-50%);border:0;border-radius:8px;background:#edf2f5;color:#475569;cursor:pointer}.auth-password-toggle:hover{background:#dfe8ec;color:#172033}.auth-password-strength{display:flex;align-items:center;gap:10px;margin-top:9px}.auth-strength-track{flex:1;height:5px;overflow:hidden;border-radius:999px;background:#e2e8f0}.auth-strength-track span{display:block;width:0;height:100%;border-radius:inherit;transition:width .25s,background .25s}.auth-strength-track .weak{background:#e11d48}.auth-strength-track .good{background:#d97706}.auth-strength-track .strong{background:#059669}.auth-password-strength strong{min-width:105px;color:#64748b;font-size:10px;text-align:right}.auth-password-strength strong.weak{color:#be123c}.auth-password-strength strong.good{color:#b45309}.auth-password-strength strong.strong{color:#047857}.auth-password-rules{display:grid;grid-template-columns:repeat(2,1fr);gap:5px 12px;margin:10px 0 0;padding:0;list-style:none}.auth-password-rules li{position:relative;padding-left:17px;color:#64748b;font-size:10px}.auth-password-rules li:before{position:absolute;left:0;content:'○';font-weight:900}.auth-password-rules li.passed{color:#047857}.auth-password-rules li.passed:before{content:'✓'}.auth-password-match{min-height:16px;margin:5px 0 0;font-size:10px}.auth-password-match.matches{color:#047857}.auth-password-match.mismatch{color:#be123c}
    @media(max-width:980px){.auth-page{grid-template-columns:1fr;justify-items:center;padding:130px 20px 60px}.auth-page:after{background:rgba(12,25,31,.34)}.auth-visual-copy{display:none}.auth-card{justify-self:center}.auth-card-scroll{max-height:none;overflow:visible}}
    @media(max-width:550px){.auth-page{padding:110px 13px 42px}.auth-card{padding:27px 22px;border-radius:19px}.auth-row{align-items:stretch;flex-direction:column}.auth-row .auth-submit{width:100%}.auth-password-rules{grid-template-columns:1fr}}
    @media(prefers-reduced-motion:reduce){.auth-page:before,.auth-card{animation:none}}
</style>
@endpush
